export function sumKnown(values) {
  if (!Array.isArray(values) || values.length === 0) {
    return null;
  }

  let sum = 0;
  for (const value of values) {
    if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
      return null;
    }
    if (sum > Number.MAX_SAFE_INTEGER - value) {
      return null;
    }
    sum += value;
  }

  return sum;
}

export function remainingPhases(kind, completed) {
  if (kind !== 'runtime' && kind !== 'documentation') {
    throw new Error();
  }
  if (!Array.isArray(completed)) {
    throw new Error();
  }
  const expected = kind === 'runtime' ? ['code', 'docs', 'review'] : ['docs', 'review'];
  if (completed.some((item, index) => item !== expected[index])) {
    throw new Error();
  }
  if (completed.length !== expected.length && kind === 'documentation') {
    throw new Error();
  }
  return expected.filter(item => !completed.includes(item));
}

export function sumKnown(values) {
  if (!Array.isArray(values) || values.length === 0) return null;
  let sum = 0;
  for (const v of values) {
    if (typeof v !== 'number' || !Number.isSafeInteger(v) || v < 0) return null;
    sum += v;
    if (!Number.isSafeInteger(sum)) return null;
  }
  return sum;
}

export function remainingPhases(kind, completed) {
  if (kind !== 'runtime' && kind !== 'documentation') {
    throw new Error('Invalid kind');
  }

  if (!Array.isArray(completed)) {
    throw new Error('Completed must be an array');
  }

  if (kind === 'runtime') {
    if (completed.length === 1) {
      if (completed[0] === 'code') {
        return ['docs', 'review'];
      }
    } else if (completed.length === 2) {
      if (completed[0] === 'code' && completed[1] === 'docs') {
        return ['review'];
      }
    }

    throw new Error('Invalid completed phases for runtime');
  }

  if (completed.length === 1 && completed[0] === 'docs') {
    return ['review'];
  }

  throw new Error('Invalid completed phases for documentation');
}

